// Mirrors the Pydantic contracts of src/hospitalos/hybrid (HYBRID_MVP_2, HYBRID_PLAN_4/5,
// LIVE_UNIT_SNAPSHOT_1, SHADOW_EPISODE_1, UNIT_SOURCE_QUALITY_1). Datetimes are ISO UTC strings.
// Keep in sync with the backend: src/fixtures are generated by the real planner and
// typecheck against these types (see contract.test.ts).

export type ISODate = string;

export interface Unit {
  kind: "unit";
  id: string;
  staffed_beds: number | null;
  cleaning_teams: number | null;
}

export type BedState = "clean" | "dirty" | "occupied" | "closed" | "unknown";

export interface Bed {
  kind: "bed";
  id: string;
  unit_id: string;
  state: BedState;
  capabilities: string[];
  occupant: string | null;
  reserved_for: string | null;
}

export interface Patient {
  kind: "patient";
  id: string;
  status: "waiting" | "admitted" | "departed";
  compatible_units: string[];
  requirements: string[];
  priority: number;
  waiting_since: ISODate;
  bed_id: string | null;
  medically_cleared: boolean | null;
  downstream_confirmed: boolean | null;
}

export interface ResourcePool {
  kind: "pool";
  id: string;
  resource: "transport" | "downstream";
  unit_ids: string[];
  available: number | null;
}

export interface Discharge {
  kind: "discharge";
  id: string;
  documents_ready: boolean | null;
  escort_required: boolean | null;
  escort_confirmed: boolean | null;
  downstream_required: boolean | null;
  downstream_pool_id: string | null;
  transport_required: boolean | null;
  transport_pool_id: string | null;
  transport_requested: boolean | null;
}

export type Fact = Unit | Bed | Patient | ResourcePool | Discharge;

export interface FactEvent {
  schema_version: "HYBRID_MVP_2";
  hospital_id: string;
  event_id: string;
  version: number;
  source: string;
  event_time: ISODate;
  available_at: ISODate;
  fact: Fact;
}

export interface State {
  hospital_id: string;
  at: ISODate;
  fingerprint: string;
  units: Unit[];
  beds: Bed[];
  patients: Patient[];
  pools: ResourcePool[];
  discharges: Discharge[];
  issues: string[];
  warnings: string[];
}

export type ActionKind = "no_op" | "prioritize_cleaning" | "reserve_bed" | "request_transport";

export interface Action {
  kind: ActionKind;
  bed_id: string | null;
  patient_id: string | null;
}

export interface Candidate {
  action: Action;
  mean_waiting_patient_minutes: number;
  worst_decile_waiting_patient_minutes: number;
  objective: number;
  violations: string[];
  scenarios_with_unserved_demand: number;
  max_waiting_at_end: number;
  max_arrived: number;
  mean_staffed_pressure: number;
  mean_cleaning_pressure: number;
  mean_transport_pressure: number;
  mean_downstream_pressure: number;
  pressure_regression_scenarios: number;
}

export interface Assumptions {
  provenance: "synthetic_hypothesis";
  version: string;
  cleaning_minutes: number[];
  departure_minutes: number[];
  transport_minutes: number[];
  transport_return_minutes: number[];
  load_multipliers: number[];
}

export interface ArrivalBatch {
  id: string;
  minute_options: number[];
  count_options: number[];
  compatible_units: string[];
  requirements: string[];
  priority: number;
}

export type FutureChange =
  | {
      kind: "resource_change";
      id: string;
      minute: number;
      resource: "staffed_beds" | "cleaning_teams" | "transport" | "downstream";
      target_id: string;
      capacity: number;
    }
  | { kind: "bed_admissions"; id: string; minute: number; bed_id: string; admissions_open: boolean };

export interface FutureAssumptions {
  schema_version: "HYBRID_FUTURE_1";
  provenance: "synthetic_hypothesis";
  declared_at: ISODate;
  arrivals: ArrivalBatch[];
  changes: FutureChange[];
}

export type ReadinessStage =
  "medical_not_confirmed" | "logistics_blocked" | "transport_to_request" | "ready_for_simulation";

export interface DischargeReadiness {
  patient_id: string;
  stage: ReadinessStage;
  blockers: string[];
}

export type Decision = "recommend" | "no_change" | "abstain";

export interface Plan {
  schema_version: "HYBRID_PLAN_4" | "HYBRID_PLAN_5";
  evidence: "simulation_under_declared_assumptions";
  decision: Decision;
  plan_id: string;
  hospital_id: string;
  state_fingerprint: string;
  created_at: ISODate;
  expires_at: ISODate;
  selected: Action;
  reasons: string[];
  warnings: string[];
  candidates: Candidate[];
  candidates_truncated: boolean;
  assumptions: Assumptions;
  future: FutureAssumptions | null;
  preparation: unknown | null;
  seed: number;
  scenarios: number;
  horizon_minutes: number;
  tail_weight: number;
  discharge_readiness: DischargeReadiness[];
  service_status: "not_assessed" | "served_in_all_sampled_scenarios" | "unserved_in_some_sampled_scenarios";
}

export interface PlanRequest {
  hospital_id: string;
  at: ISODate;
  expected_entities: string[];
  events: FactEvent[];
  assumptions: Assumptions;
  future: FutureAssumptions | null;
  preparation: unknown | null;
  max_age_minutes: number;
  horizon_minutes: number;
  scenarios: number;
  max_candidates: number;
  seed: number;
  tail_weight: number;
}

// --- Live unit (shadow) ---------------------------------------------------

export type Resource = "staffed" | "cleaning" | "transport" | "downstream";

export interface Availability {
  resource: Resource;
  target_id: string;
  available: number | null;
  source: string;
  observed_at: ISODate;
  evidence_ref: string;
}

export interface ResourceBudget {
  key: string;
  observed_available: number | null;
  held: number;
  remaining: number | null;
  observations: Availability[];
  issues: string[];
}

export interface LiveSnapshot {
  schema_version: "LIVE_UNIT_SNAPSHOT_1";
  mode: "shadow" | "sandbox";
  state: State;
  manifest_version: number;
  expected_entities: string[];
  events: FactEvent[];
  resources: ResourceBudget[];
  received_at_by_source: Record<string, string>;
  semantic_fingerprint: string;
  policy_fingerprint: string;
  issues: string[];
  warnings: string[];
}

export interface PlanningOptions {
  assumptions?: Assumptions;
  horizon_minutes?: number;
  scenarios?: number;
  seed?: number;
}

export interface LiveAssessment {
  schema_version: "LIVE_ASSESSMENT_1";
  snapshot: LiveSnapshot;
  plan: Plan | null;
  gate_reasons: string[];
  expires_at: ISODate;
}

export interface ShadowEpisode {
  schema_version: "SHADOW_EPISODE_1";
  episode_id: string;
  mode: "shadow_only_no_execution";
  assessment: LiveAssessment;
  commands_emitted: 0;
  causal_effect_established: false;
}

export interface ShadowSummary {
  schema_version: "SHADOW_SUMMARY_1";
  episodes: number;
  blocked_episodes: number;
  planner_decisions: Record<string, number>;
  gate_reason_counts: Record<string, number>;
  commands_emitted: 0;
  causal_effect_established: false;
  interpretation: string;
}

// --- Source qualification ---------------------------------------------------

export interface SourceIssue {
  code: string;
  kind: string | null;
  field: string | null; // canonical field name only, never a source value
  count: number;
}

export interface QualityReport {
  schema_version: "UNIT_SOURCE_QUALITY_1";
  status: "REJECTED" | "OBSERVATION_ONLY" | "SHADOW_EVALUATED";
  receipt_at: ISODate;
  evaluation_mode: "quality_only" | "shadow";
  state_ready: boolean | null;
  shadow_episode_created: boolean;
  profile_fingerprint: string;
  content_fingerprint: string;
  records_by_kind: Record<string, number>;
  expected_entities: number | null;
  delivered_entities: number | null;
  missing_values_by_field: Record<string, number>;
  issues: SourceIssue[];
  state_gate_counts: Record<string, number>;
  max_fact_age_seconds: number | null;
  max_source_delay_seconds: number | null;
  max_resource_age_seconds: number | null;
  export_transfer_seconds: number | null;
  commands_emitted: 0;
  clinical_validation: false;
}

export interface SourceReceipt {
  report: QualityReport;
  duplicate: boolean;
  current_state_assessed: boolean;
  episode_id: string | null;
}

// --- Simulation trace (CLI --show-trace / fixtures only) ---------------------

export interface Transition {
  minute: number;
  kind: string;
  patient_id: string | null;
  bed_id: string;
  resource_id: string | null;
  external_id: string | null;
}

export interface TraceScore {
  waiting_patient_minutes: number;
  admitted: number;
  waiting_at_end: number;
  violations: string[];
  arrived: number;
  cancelled_reservations: number;
  pressure: Record<string, number>;
}

export interface PairedTrace {
  baseline: { trajectory: { horizon_minutes: number; events: Transition[] }; score: TraceScore };
  selected: { trajectory: { horizon_minutes: number; events: Transition[] }; score: TraceScore };
}
